return {["fb22_01"]={["down"]=[[fb22_04]],["dsc"]=[[这是一面山坡，山势甚为平坦。山坡上有几间茅屋。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb22_01]],["name"]=[[山坡]],["permission"]=2,["right"]=[[fb22_02]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb22_02"]={["down"]=[[fb22_05]],["dsc"]=[[只见姹紫嫣红，满山锦绣，彩蝶纷飞，群蜂轻舞。纵是宇外琼地，世外桃源，也不过如此。]],["enterable"]=1,["id"]=[[fb22_02]],["item1"]=[[pzrw]],["left"]=[[fb22_01]],["name"]=[[落英谷内]],["permission"]=1,["right"]=[[fb22_03]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb22_03"]={["down"]=[[fb22_61]],["dsc"]=[[这是一面山谷。由于山坡向南，阻住了山风，加之地下矿藏丰富，所以地气极暖，百花先放。此处架着几个木架，托着七八个蜂巢。但见群蜂争舞，到处都是嗡嗡声。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb22_03]],["item1"]=[[fb22item324]],["item2"]=[[fb22item323]],["left"]=[[fb22_02]],["name"]=[[山谷中]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb22_04"]={["dsc"]=[[这是间陈设简单的木屋，屋角边靠着一张竹床，桌旁用木桩做凳，他人只知住在这里的老前辈姓周，来历不详，极擅玩乐寻趣。]],["enterable"]=1,["id"]=[[fb22_04]],["item1"]=[[fb22item6]],["name"]=[[周前辈居]],["permission"]=2,["role1"]=[[fb22r04_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_01]],["visible"]=1},["fb22_05"]={["down"]=[[fb22_06]],["dsc"]=[[来到此处，你突然眼前一亮，但觉青青翠谷，点缀着或红或紫，或黄或白的鲜花，竟是换了一个世界。道旁有一株桃树，开得正艳。]],["enterable"]=1,["id"]=[[fb22_05]],["item1"]=[[ycitem1]],["name"]=[[落英谷]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb22_02]],["visible"]=1},["fb22_06"]={["down"]=[[fb22_07]],["dsc"]=[[这里是白茫茫的一片雪地，远处山峰层峦迭嶂。前面隐隐约约好像有一个山谷。阵阵花香飘过来，好像还夹杂着鸟的欢唱。]],["enterable"]=1,["id"]=[[fb22_06]],["item1"]=[[fb22item302]],["item2"]=[[bfitem2]],["name"]=[[茫茫雪地]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb22_05]],["visible"]=1},["fb22_07"]={["down"]=[[fb22_08]],["dsc"]=[[眼前一片光明，比起树林里的黑暗，简直有点刺眼。南边是一片阴森森的大树林，相信你是不敢再进去了。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb22_07]],["item1"]=[[fb22item304]],["item2"]=[[fb22item313]],["name"]=[[树林外]],["permission"]=1,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_06]],["visible"]=1},["fb22_08"]={["down"]=[[fb22_23]],["dsc"]=[[丛林中一片黑暗，你瞪大眼睛，觉得到处都是路，又好像到处都不是路。若是在丛林中迷失了方向，这辈子就别想活着走出去了。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb22_08]],["item1"]=[[2020qmjs1]],["name"]=[[树林]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb22_07]],["visible"]=1},["fb22_09"]={["dsc"]=[[这是一条羊肠小路，北边是浓郁的大森林，不知道你进去之后还能不能出来。你走着走着，不禁害怕起来。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb22_09]],["item1"]=[[fb22item321]],["name"]=[[小路]],["permission"]=1,["rightDown"]=[[fb22_20]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_28]],["visible"]=1},["fb22_10"]={["down"]=[[fb22_11]],["dsc"]=[[这里是神秘前辈的剑冢，几块大石磊成一个石堆。]],["enterable"]=1,["id"]=[[fb22_10]],["item1"]=[[fb22item5]],["item2"]=[[fb22item4]],["item3"]=[[fb22item13]],["name"]=[[剑冢]],["permission"]=2,["right"]=[[fb22_33]],["role1"]=[[fb22r10_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb22_11"]={["down"]=[[fb22_12]],["dsc"]=[[待你走进了看，着峭壁上刻着剑冢二字。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb22_11]],["name"]=[[峭壁中]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb22_10]],["visible"]=1},["fb22_12"]={["down"]=[[fb22_13]],["dsc"]=[[那峭壁便如一座极大的屏风，冲天而起，峭壁中部离地约二十馀丈处，生着一块三四丈见方的大石，便似一个平台，石上隐隐刻得有字。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb22_12]],["name"]=[[峭壁]],["permission"]=2,["right"]=[[fb22_59]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_11]],["visible"]=1},["fb22_13"]={["down"]=[[fb22_14]],["dsc"]=[[你穿过了深谷，来到了一片小树林，前方就是峭壁所在了。]],["enterable"]=1,["fightBackground"]=[[谷后树林]],["id"]=[[fb22_13]],["item1"]=[[ycitem5]],["name"]=[[谷后树林]],["permission"]=2,["right"]=[[fb22_70]],["role1"]=[[fb22r13_100]],["role2"]=[[fb22r13_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_12]],["visible"]=1},["fb22_14"]={["down"]=[[fb22_16]],["dsc"]=[[这里是一座深谷，前面有一片小树林。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb22_14]],["item1"]=[[bfitem3]],["name"]=[[深谷]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb22_13]],["visible"]=1},["fb22_15"]={["down"]=[[fb22_17]],["dsc"]=[[这洞其实甚浅，行不到三丈，已抵尽头，洞中除了一张石桌、一张石凳之外更无别物。洞角有一堆乱石高起，极似一个坟墓，洞壁上似乎写得有字，只是尘封苔蔽，黑暗中瞧不清楚。传言这里是某神秘前辈的埋骨处，前辈生前因难逢对手而深感寂寥无奈，故隐居于此。]],["enterable"]=1,["id"]=[[fb22_15]],["item1"]=[[fb22item7]],["name"]=[[神秘人埋骨之洞]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb22_16"]={["down"]=[[fb22_18]],["dsc"]=[[这里是一个深谷，往北走似乎是一堵峭壁。]],["enterable"]=1,["id"]=[[fb22_16]],["name"]=[[深谷]],["permission"]=1,["right"]=[[fb22_17]],["role1"]=[[fb22r16_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_14]],["visible"]=1},["fb22_17"]={["dsc"]=[[这里是一个小小的山洞，似乎还可以往里走。]],["enterable"]=1,["id"]=[[fb22_17]],["left"]=[[fb22_16]],["name"]=[[山洞]],["permission"]=1,["role1"]=[[fb22r17_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_15]],["visible"]=1},["fb22_18"]={["down"]=[[fb22_19]],["dsc"]=[[这里是一道山谷，你大声呼喊，传来阵阵回音。]],["enterable"]=1,["id"]=[[fb22_18]],["item1"]=[[bfitem4]],["item2"]=[[ycitem4]],["name"]=[[山谷]],["permission"]=1,["role1"]=[[fb22r18_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_16]],["visible"]=1},["fb22_19"]={["down"]=[[fb22_21]],["dsc"]=[[这里是一道山谷，你大声呼喊，传来阵阵回音。]],["enterable"]=1,["id"]=[[fb22_19]],["name"]=[[山谷]],["permission"]=1,["right"]=[[fb22_58]],["role1"]=[[fb22r19_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_18]],["visible"]=1},["fb22_20"]={["dsc"]=[[这里的路面更加陡峭，地上的足迹越来越少。一阵阵腐朽的味从密林里面传出。偶尔能看见一些猎户们捕捉野兽的陷阱。]],["enterable"]=1,["id"]=[[fb22_20]],["item1"]=[[fb22item322]],["item2"]=[[bfitem1]],["leftDown"]=[[fb22_22]],["leftUp"]=[[fb22_09]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb22_21]],["role1"]=[[fb22r20_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb22_21"]={["dsc"]=[[这里是一片一望无垠林海，每棵树木都有十来丈高，周围阡陌交错，你进来感觉到自己迷路了。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb22_21]],["item1"]=[[fb22item8]],["item2"]=[[fb22item8]],["item3"]=[[fb22item8]],["item4"]=[[fb22item8]],["left"]=[[fb22_20]],["name"]=[[树林]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb22_40]],["visible"]=1},["fb22_22"]={["dsc"]=[[这里是山麓上唯一的一条土路，山势虽然并不算太高，但是极为陡峭，四周丛林密部，不时传来野兽的鸣叫。]],["enterable"]=1,["id"]=[[fb22_22]],["item1"]=[[fb22item318]],["item2"]=[[fb22rc1]],["name"]=[[山路]