["left"]=[[fb22_19]],["name"]=[[山门]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb22_57]]},["fb22_59"]={["dsc"]=[[那峭壁便如一座极大的屏风，冲天而起，峭壁中部离地约二十馀丈处，生着一块三四丈见方的大石，便似一个平台，石上隐隐刻得有字。]],["id"]=[[fb22_59]],["item1"]=[[ycitem7]],["left"]=[[fb22_12]],["name"]=[[峭壁]],["permission"]=2,["right"]=[[fb22_60]],["stepMusic"]=[[jiaobu]]},["fb22_60"]={["dsc"]=[[这棵榕树生长在峭壁之上，粗壮的树根盘绕在一起。树根中间有一个缝隙，里面是树根架起来的天然树屋。树屋之中摆放一应俱全，一名白发男子正在作画。]],["id"]=[[fb22_60]],["item1"]=[[fb22item300]],["left"]=[[fb22_59]],["name"]=[[树屋]],["permission"]=2,["role1"]=[[fb22r33_100]],["stepMusic"]=[[jiaobu]]},["fb22_61"]={["dsc"]=[[这间木屋隐在百花丛中，造型小巧精致，家用物件一应俱全。木屋里里外外被打扫的干干净净，门半掩着，似乎有人居住。]],["id"]=[[fb22_61]],["item1"]=[[fb22item301]],["item2"]=[[fb22item303]],["name"]=[[小木屋]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb22_03]]},["fb22_62"]={["dsc"]=[[一个破败不堪的山神庙，地板已经十分腐朽，长满青苔，踩上去咯吱作响。窗户开了个大窟窿。墙体之上全是蜘蛛网。山神像被人随意丢弃在一旁。山神庙后有一个通道。]],["id"]=[[fb22_62]],["left"]=[[fb22_22]],["name"]=[[破山神庙]],["permission"]=2,["right"]=[[fb22_63]],["role1"]=[[fb22r62_1]],["role2"]=[[rybritem1]],["stepMusic"]=[[jiaobu]]},["fb22_63"]={["down"]=[[fb22_66]],["dsc"]=[[这里便是重光教其中一处分舵。分舵之内设施齐全，四通八达，是一处不错的避世之所。]],["id"]=[[fb22_63]],["left"]=[[fb22_62]],["name"]=[[重光分舵]],["permission"]=2,["right"]=[[fb22_64]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_68]]},["fb22_64"]={["down"]=[[fb22_67]],["dsc"]=[[一个不大的广场，广场修建的十分平整。两旁设有石凳，可供人休息。]],["id"]=[[fb22_64]],["left"]=[[fb22_63]],["name"]=[[广场]],["permission"]=2,["right"]=[[fb22_65]],["role1"]=[[fb22r64_1]],["role2"]=[[fb22r64_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_69]]},["fb22_65"]={["dsc"]=[[重光分舵的正殿，是侍从商议大事的场所。正殿修建十分气派，左右梁柱之上各自雕刻着日月之神，正中红毯铺地，踩上去十分柔软。正殿深处是侍从的宝座，由纯银打造而成，雕工精致，侍从平时便在宝座之上传播教义。]],["id"]=[[fb22_65]],["item1"]=[[fb22rc]],["left"]=[[fb22_64]],["name"]=[[正殿]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb22_66"]={["dsc"]=[[这里是储放杂物的地方，与其说是储物间，倒不如说是垃圾堆。各种各样的杂物被堆积其中，散发着难闻的气味。]],["id"]=[[fb22_66]],["name"]=[[储物间]],["permission"]=2,["role1"]=[[rybritem3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_63]]},["fb22_67"]={["dsc"]=[[这里是祭祀月神谦和的场所。谦和是重光教所崇拜的月亮之神，以女子之身现世，赋予人世情感，柔和的月光倾洒大地，万物便能获得灵性。]],["id"]=[[fb22_67]],["name"]=[[月坛]],["permission"]=2,["role1"]=[[rybritem5]],["stepMusic"]=[[jiaobu]],["up"]=[[fb22_64]]},["fb22_68"]={["down"]=[[fb22_63]],["dsc"]=[[这里是储存粮食的地方。乞丐们每天可在这里领取粮食。虽然食住无忧，但大多数乞丐还是勤俭节约，也不愿浪费粮食。]],["id"]=[[fb22_68]],["name"]=[[谷仓]],["permission"]=2,["role1"]=[[rybritem2]],["stepMusic"]=[[jiaobu]]},["fb22_69"]={["down"]=[[fb22_64]],["dsc"]=[[这里是祭祀日神尧白的场所。尧白是重光教所崇拜的太阳之神，以男子之身现世，赋予人世生命，他的光芒普照大地，万物沐浴阳光之后，便能获得生机。]],["id"]=[[fb22_69]],["name"]=[[日坛]],["permission"]=2,["role1"]=[[rybritem4]],["stepMusic"]=[[jiaobu]]},["fb22_70"]={["dsc"]=[[那峭壁便如一座极大的屏风，冲天而起，峭壁中部离地约二十馀丈处，生着一块三四丈见方的大石，便似一个平台，石上隐隐刻得有字。]],["id"]=[[fb22_70]],["item1"]=[[sbzq1]],["left"]=[[fb22_13]],["name"]=[[峭壁]],["permission"]=2,["stepMusic"]=[[jiaobu]]}}000